<?php $this->assign('title', h($user->name) . ' | Usuarios'); ?>
<div class="d-flex justify-content-between gap-3 mb-4 page-heading"><div><a class="small" href="/admin/users">← Usuarios</a><h1 class="h2 mb-1"><?= h($user->name) ?></h1><p class="text-muted mb-0"><?= h($user->email) ?> · registrado <?= h($user->created) ?></p></div><span class="badge text-bg-<?= $user->active ? 'success' : 'secondary' ?> align-self-center"><?= $user->active ? 'Activo' : 'Bloqueado' ?></span></div>
<div class="row g-4"><div class="col-lg-8"><section class="card admin-card mb-4"><div class="card-body"><h2 class="h5">Cuenta y uso</h2><dl class="row mb-0"><dt class="col-sm-4">Rol</dt><dd class="col-sm-8"><?= h($user->role === 'customer' ? 'user' : $user->role) ?></dd><dt class="col-sm-4">Correo verificado</dt><dd class="col-sm-8"><?= $user->email_verified ? 'Sí' : 'No' ?></dd><dt class="col-sm-4">Plan actual</dt><dd class="col-sm-8"><?= h($currentSubscription->plan_slug ?? 'Sin suscripción') ?> · <?= h($currentSubscription->status ?? '') ?></dd><dt class="col-sm-4">Vitrinas</dt><dd class="col-sm-8"><?= (int)$usage['configured'] ?> configuradas · <?= (int)$usage['published'] ?> publicadas</dd></dl></div></section>
<section class="card admin-card mb-4"><div class="card-body"><h2 class="h5">Vitrinas</h2><div class="table-wrap"><table class="table table-sm"><thead><tr><th>Nombre</th><th>Subdominio</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach ($user->sites as $site): ?><tr><td><?= h($site->name) ?></td><td><?= h($site->subdomain) ?></td><td><?= h($site->status) ?></td><td><a href="/admin/sites/<?= (int)$site->id ?>">Ver</a></td></tr><?php endforeach; ?></tbody></table></div></div></section>
<section class="card admin-card"><div class="card-body"><h2 class="h5">Historial de pagos</h2><div class="table-wrap"><table class="table table-sm"><thead><tr><th>Referencia</th><th>Estado</th><th>Monto</th><th></th></tr></thead><tbody><?php foreach ($user->payments as $payment): ?><tr><td><?= h($payment->internal_reference) ?></td><td><?= h($payment->status) ?></td><td>$<?= number_format((int)$payment->amount, 0, ',', '.') ?></td><td><a href="/admin/payments/<?= (int)$payment->id ?>">Ver</a></td></tr><?php endforeach; ?></tbody></table></div></div></section></div>
<aside class="col-lg-4"><section class="card admin-card mb-4"><div class="card-body"><h2 class="h5">Acciones</h2><?php if (!$user->email_verified): ?><?= $this->Form->create(null, ['url' => '/admin/users/' . $user->id . '/verify', 'class' => 'mb-2', 'data-admin-confirm' => '¿Verificar manualmente este correo?']) ?><?= $this->Form->hidden('reason', ['value' => 'Verificación manual desde backoffice']) ?><?= $this->Form->button('Verificar correo', ['class' => 'btn btn-primary w-100']) ?><?= $this->Form->end() ?><?php endif; ?><?= $this->Form->create(null, ['url' => '/admin/users/' . $user->id . '/access', 'class' => 'mb-2', 'data-admin-confirm' => $user->active ? '¿Bloquear el acceso de este usuario?' : '¿Habilitar el acceso de este usuario?']) ?><input class="form-control form-control-sm mb-2" name="reason" required maxlength="500" placeholder="Motivo"><button class="btn btn-outline-<?= $user->active ? 'danger' : 'success' ?> w-100"><?= $user->active ? 'Bloquear acceso' : 'Habilitar acceso' ?></button><?= $this->Form->end() ?><?php if (($currentUser['role'] ?? '') === 'superadmin'): ?><?= $this->Form->create(null, ['url' => '/admin/users/' . $user->id . '/role', 'class' => 'mb-2', 'data-admin-confirm' => '¿Cambiar el rol de este usuario?']) ?><select class="form-select form-select-sm mb-2" name="role"><?php foreach (['user', 'admin', 'superadmin'] as $role): ?><option value="<?= $role ?>" <?= $user->role === $role ? 'selected' : '' ?>><?= $role ?></option><?php endforeach; ?></select><input class="form-control form-control-sm mb-2" name="reason" required maxlength="500" placeholder="Motivo"><button class="btn btn-outline-primary w-100">Cambiar rol</button><?= $this->Form->end() ?><?php endif; ?></div></section><section class="card admin-card mb-4"><div class="card-body"><h2 class="h5">Nota administrativa</h2><?= $this->Form->create(null, ['url' => '/admin/users/' . $user->id . '/note']) ?><textarea class="form-control mb-2" name="reason" required maxlength="500" placeholder="Nota interna"></textarea><button class="btn btn-outline-secondary w-100">Registrar nota</button><?= $this->Form->end() ?></div></section><section class="card admin-card"><div class="card-body"><h2 class="h5">Auditoría</h2><?php foreach ($audits as $audit): ?><div class="border-bottom py-2"><strong class="small"><?= h($audit->action) ?></strong><small class="d-block text-muted"><?= h($audit->created) ?></small></div><?php endforeach; ?></div></section></aside></div>
